mapper.select:
SELECT DISTINCT su.badge as USER_NUM, su.empname as REALNAME, su.badge as LOGIN_NAME, sd.DEPID as DEPT_CODE, sd.LOCATION as DEPT_NAME, so.COMPID as ORG_CODE, so.LOCATION as ORG_NAME, sr.ROL_ID as ROLE_CODE, sr.ROL_NAME as ROLE_NAME FROM comm_employee su join comm_operator co on co.userid = su.badge left join comm_department sd on sd.DEPID = su.DEPID left join comm_organization so on so.COMPID = su.COMPID left join im_user_role_rel sor on sor.URR_USERID = co.userid left join im_role sr on sr.ROL_ID = sor.URR_ROLEID where su.isdisabled = 0 and so.isdisabled = 0 and sd.isdisabled = 0 and sr.sys_type = 1
AND su.badge = #{userNum}
AND su.badge = #{loginName}
AND su.badge IN
#{userLoginName}
AND su.empname = #{realname}
AND su.empname LIKE #{LikeRealNameLike}
AND sd.DEPID IN
#{deptCode}
AND so.COMPID IN
#{orgCode}
AND sr.ROL_ID IN
#{roleCode}

SELECT DISTINCT ce.compid ORG_CODE, ir.rol_id as ROLE_CODE, null DEPT_CODE from comm_employee ce join comm_operator co on co.userid = ce.badge join comm_organization co on co.compid = ce.compid join im_user_role_rel iurr on iurr.urr_userid = co.userid join im_role ir on ir.rol_id = iurr.urr_roleid and ir.sys_type = 1 WHERE co.compid IS NOT NULL AND ce.badge = #{userId}
UNION ALL SELECT DISTINCT null ORG_CODE, ir.rol_id ROLE_CODE, cd.depid DEPT_CODE from comm_employee ce join comm_operator co on co.userid = ce.badge join comm_department cd on cd.depid = ce.depid join im_user_role_rel iurr on iurr.urr_userid = co.userid join im_role ir on ir.rol_id = iurr.urr_roleid and ir.sys_type = 1 WHERE cd.depid IS NOT NULL AND ce.badge = #{userId}
UNION ALL SELECT DISTINCT ce.compid ORG_CODE, NULL ROLE_CODE, NULL DEPT_CODE from comm_employee ce join comm_operator co on co.userid = ce.badge join comm_organization co on co.compid = ce.compid WHERE co.compid IS NOT NULL AND ce.badge = #{userId}
UNION ALL SELECT DISTINCT NULL ORG_CODE, NULL ROLE_CODE, ce.depid as DEPT_CODE from comm_employee ce join comm_operator co on co.userid = ce.badge join comm_department cd on cd.depid = ce.depid WHERE cd.depid IS NOT NULL AND ce.badge = #{userId}
UNION ALL SELECT DISTINCT NULL ORG_CODE, ir.rol_id as ROLE_CODE, NULL DEPT_CODE from comm_employee ce join comm_operator co on co.userid = ce.badge join im_user_role_rel iurr on iurr.urr_userid = co.userid join im_role ir on ir.rol_id = iurr.urr_roleid and ir.sys_type = 1 WHERE ce.compid IS NOT NULL AND ce.badge = #{userId}
UNION ALL SELECT DISTINCT ce.compid ORG_CODE, ir.rol_id as ROLE_CODE, ce.depid as DEPT_CODE from comm_employee ce join comm_operator co on co.userid = ce.badge join comm_organization co on co.compid = ce.compid join im_user_role_rel iurr on iurr.urr_userid = co.userid join im_role ir on ir.rol_id = iurr.urr_roleid and ir.sys_type = 1 WHERE co.compid IS NOT NULL and ce.depid IS NOT NULL AND ce.badge = #{userId}
